#!/usr/bin/env python3
"""Apply approved public copy after legacy generators and verified overlays."""
from pathlib import Path
import argparse,re,html,hashlib
p=argparse.ArgumentParser();p.add_argument('--public',type=Path,required=True);root=p.parse_args().public
copy={
'es':{'title':'Colombia, un país con muchos lugares para volver','heading':'Lugares que sorprenden','intro':'Una selección de atracciones de nuestras guías publicadas. Descubre a qué lugar pertenece cada una y prepara tu próxima visita.','all':'Ver todos los lugares →','fallback':'Explora las guías publicadas para conocer sus atracciones.','measure':'Estadísticas del portal','basic':'Contamos páginas consultadas, visualizaciones de negocios y clics de contacto mediante agregados. El país de conexión se obtiene temporalmente a partir de la IP con una base local; no almacenamos la IP en estas estadísticas ni la enviamos a un proveedor de geolocalización. No usamos cookies analíticas ni identificadores para reconocer visitantes o reconstruir sus recorridos. Estos conteos no equivalen a personas únicas, conversaciones ni ventas. Conservamos los agregados históricos sin borrado automático por antigüedad. Puedes excluir este navegador mediante «Privacidad y estadísticas» del pie; esta preferencia local es independiente de las cookies necesarias para iniciar sesión y de los registros técnicos de seguridad del alojamiento.','retention':'Las condiciones de conservación de los datos personales enviados se informan junto al formulario antes de confirmar el envío. Los totales estadísticos agregados tienen un tratamiento separado, descrito abajo.'},
'en':{'title':'Colombia, a country with many places to return to','heading':'Places that surprise','intro':'A selection of attractions from our published guides. Discover where each belongs and plan your next visit.','all':'Explore all places →','fallback':'Explore our published guides and their attractions.','measure':'Portal statistics','basic':'We count page views, business views and contact clicks as aggregates. The connection country is derived temporarily from the IP using a local database; we neither store the IP in these statistics nor send it to a geolocation provider. We use no analytics cookies or identifiers to recognise visitors or reconstruct their journeys. Counts do not represent unique people, conversations or sales. Historical aggregates have no automatic age-based deletion. You can exclude this browser through “Privacy and statistics” in the footer. This local preference is separate from necessary login cookies and the hosting security logs.','retention':'Retention conditions for submitted personal data are provided next to the form before submission. Aggregate statistics are handled separately, as explained below.'},
'pt-br':{'title':'Colômbia, um país com muitos lugares para voltar','heading':'Lugares que surpreendem','intro':'Uma seleção de atrações dos nossos guias publicados. Descubra a que lugar cada uma pertence e prepare sua próxima visita.','all':'Ver todos os lugares →','fallback':'Explore os guias publicados e suas atrações.','measure':'Estatísticas do portal','basic':'Contamos consultas de páginas, visualizações de negócios e cliques de contato em totais agregados. O país da conexão é calculado temporariamente a partir do IP com uma base local; não armazenamos o IP nessas estatísticas nem o enviamos a um provedor de geolocalização. Não usamos cookies analíticos nem identificadores para reconhecer visitantes ou reconstruir percursos. Esses totais não representam pessoas únicas, conversas ou vendas. Conservamos os agregados históricos sem exclusão automática por antiguidade. É possível excluir este navegador em “Privacidade e estatísticas”, no rodapé. Essa preferência local é independente dos cookies necessários para iniciar sessão e dos registros técnicos de segurança da hospedagem.','retention':'As condições de conservação dos dados pessoais enviados são informadas junto ao formulário antes da confirmação. As estatísticas agregadas têm tratamento separado, descrito abaixo.'}}
register=re.compile(r'registr(?:ar|a)|register|list my business|cadast',re.I)
for page in root.rglob('*.html'):
 rel=page.relative_to(root).as_posix();lang='en' if rel.startswith('en/') else 'pt-br' if rel.startswith('pt-br/') else 'es';c=copy[lang];s=page.read_text();original=s
 # Match arbitrary attributes after href while preserving icons and labels.
 s=re.sub(r'(<a\b[^>]*?href=")([^"]+)("[^>]*>)(.*?)</a>',lambda m: m[1]+'/negocios/registro/?tipo=business'+m[3]+m[4]+'</a>' if 'negocios-locales/interes' in html.unescape(m[2]) and register.search(re.sub('<[^>]+>',' ',m[4])) else m[0],s,flags=re.S)
 if rel in ['index.html','en/index.html','pt-br/index.html']:
  prefix='' if lang=='es' else '/'+lang
  s=re.sub(r'(<section id="destinos" class="section">).*?</section>',lambda m:'<section id="destinos" class="section"><div class="sectionhead"><div><p class="eyebrow">'+c['title']+'</p><h2>'+c['heading']+'</h2></div><p>'+c['intro']+'</p></div><div class="home-attractions" data-home-attractions><p>'+c['fallback']+'</p></div><p><a class="text-link" href="'+prefix+'/destinos/">'+c['all']+'</a></p></section>',s,flags=re.S)
  s=s.replace('Un país de muchos lugares para <em>volver.</em>','Colombia, un país con muchos lugares para <em>volver.</em>')
  if 'portada-atracciones.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="/assets/portada-atracciones.css"></head>')
 if '/privacidad/' in '/'+rel and '</main>' in s:
  s=re.sub(r'<section id="datos-configurados">.*?</section>','',s,flags=re.S)
  s=re.sub(r'<section id="medicion-opcional">.*?</section>','',s,flags=re.S)
  s=re.sub(r'<section id="conteo-basico">.*?</section>','',s,flags=re.S)
  # Remove obsolete deployment instructions from the public policy.
  s=re.sub(r'<p>(?:La configuración de los datos del responsable|The configuration of|The data controller&#39;s details|The data controller.s details|A configuração dos dados|A configuração do controlador).*?</p>','',s,flags=re.S)
  s=s.replace('</main>','<section id="datos-configurados"><p>'+c['retention']+'</p><div data-privacy-info></div></section><section id="conteo-basico"><h2>'+c['measure']+'</h2><p>'+c['basic']+'</p><p><a href="https://db-ip.com/">IP Geolocation by DB-IP</a> · Country Lite, CC BY 4.0.</p></section></main>')
 if ('data-home-attractions' in s or 'data-privacy-info' in s) and 'portada-atracciones.js' not in s:s=s.replace('</body>','<script src="/assets/portada-atracciones.js" defer></script></body>')
 for asset in ['portada-atracciones.js','portada-atracciones.css']:
  path=root/'assets'/asset
  if path.exists():
   version=hashlib.sha256(path.read_bytes()).hexdigest()[:12]
   s=re.sub(r'/assets/'+re.escape(asset)+r'(?:\?v=[a-f0-9]+)?"','/assets/'+asset+'?v='+version+'"',s)
 if s!=original:page.write_text(s)
